SET
  @Name_3e3235c9 = N'Realtime'
SET
  @Description_3e3235c9 = N'Real-time agent type — a first-class peer of Loop and Flow that drives a streaming, full-duplex BaseRealtimeModel session (voice today, video later) instead of an iterative reasoning loop. The model owns the listen-reason-speak loop; the agent delegates real work back to async (Loop/Flow) agents via tool calls. The first agent of this type is the Voice Co-Agent, which voices on behalf of any target agent. The system prompt is per-agent (assembled at session start), so there is no type-level SystemPromptID.'
SET
  @IsActive_3e3235c9 = 1
SET
  @DriverClass_3e3235c9 = N'RealtimeAgentType'
SET
  @UIFormSectionExpandedByDefault_3e3235c9 = 0
SET
  @ConfigSchema_3e3235c9 = N'{"$schema":"http://json-schema.org/draft-07/schema#","title":"Realtime Co-Agent TypeConfiguration","description":"Configuration payload for agents of the Realtime type — the agent''s realtime profile. Effective config = AIAgentType.DefaultConfiguration <- AIAgent.TypeConfiguration <- runtime overrides (later layers win per key, deep-merged).","type":"object","additionalProperties":false,"properties":{"realtime":{"type":"object","additionalProperties":false,"properties":{"modelPreference":{"type":"string","description":"Preferred realtime AI model (name or ID). Used unless an authorized runtime override supplies a different model."},"voice":{"type":"object","additionalProperties":false,"properties":{"default":{"type":"object","additionalProperties":false,"properties":{"tone":{"type":"string","description":"Spoken tone folded into the session system prompt (e.g. ''warm, unhurried'')."},"speakingStyle":{"type":"string","description":"Speaking style folded into the session system prompt (e.g. ''concise, plain language'')."},"voice":{"type":"string","description":"Provider-AGNOSTIC voice id, used whichever vendor ends up running the session (every realtime driver reads the neutral ''voice'' key). Set this to author a voice without knowing the vendor. Wins over a ''providers.<key>.voice'' entry; the matching provider bag still contributes its other settings."},"firstMessage":{"type":"string","description":"The opening utterance the agent SPEAKS FIRST, verbatim, before the user says anything — authored here rather than in the prompt because a provider that waits for user audio produces nothing at all until it hears some, whatever the prompt says. Omit it and the agent waits for the user, as before. Wins over a ''providers.<key>.firstMessage'' entry. Honored by drivers with a provider-native opening utterance — ElevenLabs maps it to the agent.first_message override, AssemblyAI to its greeting session slot. Drivers without one ignore it and open silently."}}},"providers":{"type":"object","description":"Per-provider voice settings, keyed by provider key (openai, gemini, elevenlabs, assemblyai).","additionalProperties":{"type":"object","additionalProperties":false,"properties":{"voice":{"type":"string","description":"Provider voice name/preset (e.g. ''alloy''). Overridden by ''voice.default.voice'' when one is authored — author this OR the agnostic slot, not both. Use this only when the voice id genuinely differs per vendor."},"voiceId":{"type":"string","description":"DEPRECATED — never read by any driver; authoring it does nothing. The whole realtime driver family (including ElevenLabs, which maps it to tts.voice_id on the wire) reads the neutral ''voice'' key. Retained only so configurations that already carry it still validate; use ''voice'' instead."}}}}}},"allowUserModelOverride":{"type":"boolean","description":"When false, even authorized users cannot override the model at runtime for sessions fronted by this agent."},"narration":{"type":"object","additionalProperties":false,"properties":{"paceMs":{"type":"number","description":"Minimum milliseconds between spoken progress narrations while delegated work runs."}}},"disclosure":{"type":"string","enum":["silent","mention","hand-voice"],"description":"Default delegation disclosure — how the co-agent narrates handing a request to a colleague: ''mention'' (name the handoff aloud), ''silent'' (absorb and speak the result as its own), ''hand-voice'' (reserved). Absent => ''mention''. Overridable by app AgentSettings and per-target."},"allowedAgents":{"type":"array","description":"Delegation targets the lead co-agent may invoke via invoke-target-agent. UNION-accumulated across cascade layers (type/co-agent/target/app) + dynamic registrations; never array-replaced.","items":{"type":"object","additionalProperties":false,"properties":{"agentId":{"type":"string","description":"The target agent''s MJ: AI Agents ID (loop or flow)."},"label":{"type":"string","description":"Friendly name for the capability manifest / disclosure narration."},"disclosure":{"type":"string","enum":["silent","mention","hand-voice"],"description":"Per-target disclosure override; falls back to the effective default."}},"required":["agentId"]}}}}}}'
SET
